package com.example.viettel.feature.feedback.presentation

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.example.viettel.feature.feedback.data.repository.FeedbackRepositoryImpl
import com.example.viettel.feature.feedback.domain.entity.FeedbackData
import com.example.viettel.feature.feedback.domain.entity.FeedbackReason
import com.example.viettel.feature.feedback.domain.usecase.SubmitFeedbackUseCase
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class FeedbackViewModel(
    private val submitFeedbackUseCase: SubmitFeedbackUseCase,
) : ViewModel() {

    private val _uiState = MutableStateFlow(FeedbackUiState())
    val uiState: StateFlow<FeedbackUiState> = _uiState

    fun setRating(rating: Int) {
        _uiState.value = _uiState.value.copy(rating = rating, submissionCompleted = false)
    }

    fun toggleReason(reason: FeedbackReason, checked: Boolean) {
        val updated = _uiState.value.selectedReasons.toMutableSet().apply {
            if (checked) add(reason) else remove(reason)
        }
        _uiState.value = _uiState.value.copy(selectedReasons = updated)
    }

    fun updateCustomReason(text: String) {
        _uiState.value = _uiState.value.copy(customReason = text)
    }

    fun isFeedbackValid(): Boolean {
        return _uiState.value.rating > 0 && (
            _uiState.value.rating > 4 || _uiState.value.selectedReasons.isNotEmpty()
            )
    }

    fun submitFeedback(onDone: (() -> Unit)? = null) {
        val state = _uiState.value
        if (!isFeedbackValid()) return
        viewModelScope.launch {
            val data = FeedbackData(
                rating = state.rating,
                reasons = state.selectedReasons,
                customReason = state.customReason
            )
            submitFeedbackUseCase(data)
            _uiState.value = state.copy(submissionCompleted = true)
            onDone?.invoke()
        }
    }

    data class FeedbackUiState(
        val rating: Int = 0,
        val selectedReasons: Set<FeedbackReason> = emptySet(),
        val customReason: String? = null,
        val submissionCompleted: Boolean = false,
    )

    class Factory : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            val submitUseCase = SubmitFeedbackUseCase(FeedbackRepositoryImpl())
            return FeedbackViewModel(submitUseCase) as T
        }
    }
}

package com.example.viettel.feature.identity.data.mapper

import android.graphics.Bitmap
import com.example.viettel.feature.identity.domain.entity.EidData
import com.example.viettel.feature.identity.domain.entity.EidPersonalInfo
import vn.leeon.eidsdk.data.Eid
import vn.leeon.eidsdk.jmrtd.FeatureStatus
import vn.leeon.eidsdk.jmrtd.VerificationStatus
import java.io.ByteArrayOutputStream
import java.security.MessageDigest
import java.text.SimpleDateFormat
import java.util.Locale

class EidMapper {

    private val dateFormat = SimpleDateFormat("dd/MM/yyyy", Locale.US)

    fun fromSdk(eid: Eid): EidData {
        val personalInfo = eid.personOptionalDetails?.let { details ->
            EidPersonalInfo(
                fullName = details.fullName,
                documentNumber = details.eidNumber,
                personalIdentification = details.personalIdentification,
                dateOfBirth = details.dateOfBirth,
                gender = details.gender,
                nationality = details.nationality,
                fatherName = details.fatherName,
                motherName = details.motherName,
                placeOfOrigin = details.placeOfOrigin,
                placeOfResidence = details.placeOfResidence,
                religion = details.religion,
                ethnicity = details.ethnicity,
                dateOfIssue = details.dateOfIssue,
                dateOfExpiry = details.dateOfExpiry,
            )
        }

        val certificateSummary = eid.sodFile?.docSigningCertificate?.let { cert ->
            val sha1 = try {
                MessageDigest.getInstance("SHA-1").digest(cert.encoded)
                    .joinToString("") { "%02X".format(it) }
            } catch (_: Exception) {
                "N/A"
            }
            buildString {
                appendLine("Serial: ${cert.serialNumber}")
                appendLine("Public Key: ${cert.publicKey.algorithm}")
                appendLine("Signature Algorithm: ${cert.sigAlgName}")
                appendLine("Thumbprint (SHA-1): $sha1")
                appendLine("Issuer: ${cert.issuerDN.name}")
                appendLine("Subject: ${cert.subjectDN.name}")
                appendLine("Valid From: ${dateFormat.format(cert.notBefore)}")
                appendLine("Valid To: ${dateFormat.format(cert.notAfter)}")
            }
        }

        val verificationSummary = buildVerificationStatusText(
            eid.verificationStatus,
            eid.featureStatus
        )

        val chipPortrait = eid.face?.let(::bitmapToByteArray)

        return EidData(
            personalInfo = personalInfo,
            chipPortrait = chipPortrait,
            certificateSummary = certificateSummary,
            verificationSummary = verificationSummary,
        )
    }

    private fun buildVerificationStatusText(vs: VerificationStatus?, fs: FeatureStatus?): String? {
        if (vs == null || fs == null) return null
        fun verdictToStr(v: VerificationStatus.Verdict?): String = when (v) {
            VerificationStatus.Verdict.SUCCEEDED -> "Success"
            VerificationStatus.Verdict.FAILED -> "Failed"
            else -> "Unknown"
        }
        return buildString {
            appendLine("Document check (HT): ${verdictToStr(vs.ht)}")
            appendLine("Chip Auth (CA): ${verdictToStr(vs.ca)}")
            appendLine("Country Signing (CS): ${verdictToStr(vs.cs)}")
            appendLine("Active Auth (AA): ${verdictToStr(vs.aa)}")
        }
    }

    private fun bitmapToByteArray(bitmap: Bitmap): ByteArray {
        val outputStream = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, 92, outputStream)
        return outputStream.toByteArray()
    }
}

package com.example.viettel.feature.identity.data.repository

import com.example.viettel.feature.identity.domain.entity.DocumentSession
import com.example.viettel.feature.identity.domain.entity.DocumentType
import com.example.viettel.feature.identity.domain.entity.EidData
import com.example.viettel.feature.identity.domain.entity.MrzData
import com.example.viettel.feature.identity.domain.repository.DocumentSessionRepository
import com.example.viettel.feature.identity.domain.entity.PortraitAction
import java.util.concurrent.atomic.AtomicReference

class DocumentSessionRepositoryImpl : DocumentSessionRepository {

    private val cache = AtomicReference(DocumentSession())

    override fun updateDocumentType(documentType: DocumentType) {
        cache.updateAndGet { it.copy(documentType = documentType) }
    }

    override fun updateFrontImage(imageBytes: ByteArray, rotation: Int) {
        cache.updateAndGet { it.copy(frontImage = imageBytes, frontImageRotation = rotation) }
    }

    override fun updateBackImage(imageBytes: ByteArray, rotation: Int) {
        cache.updateAndGet { it.copy(backImage = imageBytes, backImageRotation = rotation) }
    }

    override fun updateMrzData(mrzData: MrzData) {
        cache.updateAndGet { it.copy(mrzData = mrzData) }
    }

    override fun updateEidData(eidData: EidData) {
        cache.updateAndGet { it.copy(eidData = eidData) }
    }

    override fun updatePortrait(action: PortraitAction, imageBytes: ByteArray) {
        cache.updateAndGet { session ->
            val updated = session.portraitActions.toMutableMap().apply { put(action, imageBytes) }
            session.copy(portraitActions = updated)
        }
    }

    override fun updateSignature(signatureBytes: ByteArray) {
        cache.updateAndGet { it.copy(signature = signatureBytes) }
    }

    override fun getSession(): DocumentSession = cache.get()

    override fun clearPortraits() {
        cache.updateAndGet { it.copy(portraitActions = emptyMap()) }
    }
}

