package com.example.viettel.feature.identity.integration.eid

import android.content.Context
import io.reactivex.disposables.Disposable
import kotlinx.coroutines.suspendCancellableCoroutine
import net.sf.scuba.smartcards.CardServiceException
import org.jmrtd.AccessDeniedException
import org.jmrtd.BACDeniedException
import org.jmrtd.PACEException
import org.jmrtd.lds.icao.MRZInfo
import vn.leeon.eidsdk.data.Eid
import vn.leeon.eidsdk.facade.EidCallback
import vn.leeon.eidsdk.facade.EidFacade
import kotlin.coroutines.resume

class EidReaderDataSource(
    private val context: Context,
) {

    suspend fun readEid(mrzInfo: MRZInfo): Result<Eid> = suspendCancellableCoroutine { continuation ->
        var disposable: Disposable? = null

        disposable = EidFacade.handleDocumentNfcTag(context, mrzInfo, object : EidCallback {
            override fun onEidReadStart() {
                // no-op for now; progress handled in presentation layer
            }

            override fun onEidReadFinish() {
                // no-op
            }

            override fun onEidRead(eid: Eid?) {
                if (eid == null) {
                    if (continuation.isActive) continuation.resume(Result.failure(IllegalStateException("Missing eID data")))
                } else if (continuation.isActive) {
                    continuation.resume(Result.success(eid))
                }
            }

            override fun onAccessDeniedException(ex: AccessDeniedException) {
                if (continuation.isActive) continuation.resume(Result.failure(ex))
            }

            override fun onBACDeniedException(ex: BACDeniedException) {
                if (continuation.isActive) continuation.resume(Result.failure(ex))
            }

            override fun onPACEException(ex: PACEException) {
                if (continuation.isActive) continuation.resume(Result.failure(ex))
            }

            override fun onCardException(ex: CardServiceException) {
                if (continuation.isActive) continuation.resume(Result.failure(ex))
            }

            override fun onGeneralException(exception: Exception?) {
                if (continuation.isActive) continuation.resume(Result.failure(exception ?: IllegalStateException("Unknown NFC error")))
            }
        })

        continuation.invokeOnCancellation { disposable?.dispose() }
    }
}

package com.example.viettel.feature.identity.integration.face

import com.example.viettel.feature.identity.domain.entity.FaceAttributes
import com.example.viettel.feature.identity.domain.entity.ImageFrame
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.face.FaceDetection
import com.google.mlkit.vision.face.FaceDetectorOptions
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlin.coroutines.resume

class FaceDetectionDataSource {

    private val detector by lazy {
        val options = FaceDetectorOptions.Builder()
            .setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_FAST)
            .setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_ALL)
            .enableTracking()
            .build()
        FaceDetection.getClient(options)
    }

    suspend fun detect(frame: ImageFrame): Result<FaceAttributes> =
        suspendCancellableCoroutine { continuation ->
            val inputImage = InputImage.fromByteArray(
                frame.data,
                frame.width,
                frame.height,
                frame.rotation,
                InputImage.IMAGE_FORMAT_NV21
            )

            detector.process(inputImage)
                .addOnSuccessListener { faces ->
                    val face = faces.firstOrNull()
                    if (face == null) {
                        if (continuation.isActive) continuation.resume(
                            Result.failure(IllegalStateException("Khong thay khuon mat"))
                        )
                    } else {
                        val attrs = FaceAttributes(
                            smilingProbability = face.smilingProbability ?: -1f,
                            leftEyeOpenProbability = face.leftEyeOpenProbability ?: -1f,
                            rightEyeOpenProbability = face.rightEyeOpenProbability ?: -1f,
                            headYaw = face.headEulerAngleY,
                        )
                        if (continuation.isActive) continuation.resume(Result.success(attrs))
                    }
                }
                .addOnFailureListener { e ->
                    if (continuation.isActive) continuation.resume(Result.failure(e))
                }
        }
}

package com.example.viettel.feature.identity.integration.facematch

import android.util.Base64
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL

class FaceMatchRemoteDataSource {

    suspend fun compare(smilePortrait: ByteArray, chipPortrait: ByteArray): Result<Double> =
        withContext(Dispatchers.IO) {
            var connection: HttpURLConnection? = null
            try {
                val jsonBody = JSONObject().apply {
                    put("img1_base64", smilePortrait.toBase64())
                    put("img2_base64", chipPortrait.toBase64())
                }

                val url = URL("https://face-engine-api.atin.vn/api/v1/match")
                connection = url.openConnection() as HttpURLConnection
                connection.requestMethod = "POST"
                connection.setRequestProperty("Content-Type", "application/json; charset=utf-8")
                connection.setRequestProperty("Accept", "application/json")
                connection.connectTimeout = 25000
                connection.readTimeout = 15000
                connection.doOutput = true
                connection.doInput = true

                connection.outputStream.use { output ->
                    output.write(jsonBody.toString().toByteArray(Charsets.UTF_8))
                    output.flush()
                }

                val responseCode = connection.responseCode
                if (responseCode in 200..299) {
                    val response = connection.inputStream.bufferedReader(Charsets.UTF_8).use { it.readText() }
                    val jsonResponse = JSONObject(response)
                    val score = jsonResponse.optDouble("data", -1.0)
                    if (score >= 0.0) {
                        Result.success(score)
                    } else {
                        Result.failure(IllegalStateException("Invalid match score"))
                    }
                } else {
                    val errorResponse = connection.errorStream?.bufferedReader(Charsets.UTF_8)?.use { it.readText() }
                    Result.failure(IllegalStateException("Face match failed: $responseCode ${errorResponse ?: ""}".trim()))
                }
            } catch (e: Exception) {
                Result.failure(e)
            } finally {
                connection?.disconnect()
            }
        }

    private fun ByteArray.toBase64(): String = Base64.encodeToString(this, Base64.NO_WRAP)
}

package com.example.viettel.feature.identity.integration.ocr

import android.graphics.BitmapFactory
import com.example.viettel.feature.identity.domain.entity.CapturedImage
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.latin.TextRecognizerOptions
import kotlinx.coroutines.suspendCancellableCoroutine
import org.jmrtd.lds.icao.MRZInfo
import vn.leeon.eidsdk.utils.OcrUtils
import kotlin.coroutines.resume

class OcrMrzDataSource {

    private val recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)

    suspend fun extractMrz(capturedImage: CapturedImage): Result<MRZInfo> =
        suspendCancellableCoroutine { continuation ->
            val bitmap = BitmapFactory.decodeByteArray(capturedImage.data, 0, capturedImage.data.size)
            val inputImage = InputImage.fromBitmap(bitmap, capturedImage.rotationDegrees)
            val startTime = System.currentTimeMillis()

            recognizer.process(inputImage)
                .addOnSuccessListener { visionText ->
                    val elapsed = System.currentTimeMillis() - startTime
                    OcrUtils.processOcr(visionText, elapsed, object : OcrUtils.MRZCallback {
                        override fun onMRZRead(mrz: MRZInfo, timeRequired: Long) {
                            if (continuation.isActive) continuation.resume(Result.success(mrz))
                        }

                        override fun onMRZReadFailure(timeRequired: Long) {
                            if (continuation.isActive) continuation.resume(Result.failure(IllegalStateException("MRZ not found")))
                        }

                        override fun onFailure(e: Exception, timeRequired: Long) {
                            if (continuation.isActive) continuation.resume(Result.failure(e))
                        }
                    })
                }
                .addOnFailureListener { e ->
                    if (continuation.isActive) continuation.resume(Result.failure(e))
                }
        }
}

package com.example.viettel.feature.identity.presentation.mapper

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix

object BitmapMapper {
    fun fromBytes(bytes: ByteArray?, rotation: Int = 0): Bitmap? {
        if (bytes == null) return null
        val bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size) ?: return null
        if (rotation == 0) return bitmap

        val matrix = Matrix().apply { postRotate(rotation.toFloat()) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }
}

