class CaptureBackPhotoFragment : Fragment(R.layout.fragment_capture_back_photo) {

    private lateinit var previewView: PreviewView
    private lateinit var captureButton: ImageButton
    private lateinit var successTick: ImageView
    private lateinit var cameraHelper: CameraHelper

    private val identityViewModel: IdentityViewModel by activityViewModels {
        IdentityViewModel.Factory(requireActivity().application)
    }

    private var navigatedToNfc = false
    private var lastError: String? = null

    @OptIn(ExperimentalGetImage::class)
    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        previewView = view.findViewById(R.id.view_finder)
        captureButton = view.findViewById(R.id.btnCapture)
        successTick = view.findViewById(R.id.imgSuccessTick)
        ProgressUtils.animateProgressToStep(view, 4)

        (activity as? MainActivity)?.apply {
            setBackVisible(true)
            setContinueVisible(true)
            setContinueEnabled(identityViewModel.uiState.value.mrzData != null)
        }

        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                identityViewModel.uiState.collect { state ->
                    (activity as? MainActivity)?.setContinueEnabled(state.mrzData != null && !state.isLoading)
                    state.errorMessage?.let { error ->
                        if (error != lastError) {
                            lastError = error
                            Toast.makeText(requireContext(), error, Toast.LENGTH_SHORT).show()
                        }
                    }

                    if (!navigatedToNfc && state.mrzData != null) {
                        navigatedToNfc = true
                        (activity as? MainActivity)?.apply {
                            animateToStep(5)
                            replaceFragment(NfcFragment())
                        }
                    }
                }
            }
        }

        cameraHelper = CameraHelper(requireContext(), viewLifecycleOwner, previewView)
        cameraHelper.startCamera { e ->
            Toast.makeText(
                requireContext(),
                "Khong the mo camera: ${e.message}",
                Toast.LENGTH_SHORT
            ).show()
        }

        captureButton.setOnClickListener {
            (activity as? MainActivity)?.setContinueEnabled(false)
            cameraHelper.takePhoto(
                onCaptured = { imageProxy ->
                    val imageBytes = ImageProxyMapper.toJpegBytes(imageProxy)
                    val rotation = imageProxy.imageInfo.rotationDegrees
                    imageProxy.close()

                    if (imageBytes == null) {
                        Toast.makeText(requireContext(), "Khong the xu ly anh", Toast.LENGTH_SHORT).show()
                        (activity as? MainActivity)?.setContinueEnabled(identityViewModel.uiState.value.mrzData != null)
                        return@takePhoto
                    }

                    identityViewModel.onBackCaptured(imageBytes, rotation)
                    identityViewModel.extractMrz(imageBytes, rotation)
                    requireActivity().runOnUiThread { showSuccessTick() }
                },
                onFail = {
                    Toast.makeText(
                        requireContext(),
                        "Loi chup anh: ${it.message}",
                        Toast.LENGTH_SHORT
                    ).show()
                    (activity as? MainActivity)?.setContinueEnabled(identityViewModel.uiState.value.mrzData != null)
                }
            )
        }
    }

    override fun onResume() {
        super.onResume()
        ControlLightUtil.openLight()
        ControlLightUtil.setLight("5")
    }

    private fun showSuccessTick() {
        successTick.apply {
            alpha = 0f
            visibility = View.VISIBLE
            animate()
                .alpha(1f)
                .setDuration(300)
                .withEndAction {
                    postDelayed({
                        animate()
                            .alpha(0f)
                            .setDuration(300)
                            .withEndAction {
                                visibility = View.GONE
                                (activity as? MainActivity)?.setContinueEnabled(true)
                            }
                            .start()
                    }, 2000)
                }
                .start()
        }

        Toast.makeText(
            requireContext(),
            "Anh mat sau da chup xong!",
            Toast.LENGTH_SHORT
        ).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        ControlLightUtil.closeLight()
        cameraHelper.releaseCamera()
    }
}

