    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        ProgressUtils.animateProgressToStep(view, 7)
        (activity as? MainActivity)?.apply {
            setContinueVisible(false)
            setBackVisible(true)
        }

        val circularProgress = view.findViewById<CircularProgressIndicator>(R.id.circularProgress)
        val btnCancelPayment = view.findViewById<Button>(R.id.btnCancelPayment)

        btnCancelPayment.setOnClickListener {
            paymentViewModel.cancelPayment()
            requireActivity().supportFragmentManager.popBackStack()
        }

        observeState(circularProgress)
        paymentViewModel.startPaymentIfNeeded()
