        if(input == null || input.length() == 0){
            return "";
        }

        input = input.trim();
        if(input.startsWith("0")){
            input = input.substring(1, input.length());
            removeFirstZeroNumber(input);
        }else{
            return input;
        }

        return  input;
    }


